INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (5,5,'["Quels outils ou méthodes utilisez-vous pour élaborer et suivre un budget prévisionnel dans un contexte organisationnel complexe ?", "Comment procédez-vous pour analyser les écarts entre les réalisations financières et les objectifs fixés, et quelles actions correctives proposez-vous habituellement ?", "Quelle est votre approche pour mettre en place un tableau de bord de gestion permettant de piloter la performance d''une structure comme une agence de développement régional ?", "Pouvez-vous nous décrire le contexte de votre expérience de 4 ans et les missions de gestion ou de contrôle qui vous ont le plus préparé à ce poste ?", "Avez-vous déjà géré des projets ou des dossiers en lien avec des financements publics ou des partenariats institutionnels ? Si oui, décrivez un exemple concret.", "Quelle a été la situation professionnelle la plus complexe que vous avez gérée, et comment l''avez-vous résolue ?", "Pourquoi souhaitez-vous rejoindre l''ADER Fès-Meknès à ce stade de votre parcours, et qu''espérez-vous apporter à cette structure ?", "Où vous voyez-vous professionnellement dans 5 ans, et en quoi ce poste de CGM s''inscrit-il dans votre projet de carrière ?", "Que savez-vous des missions principales de l''ADER Fès-Meknès et de son rôle dans le développement économique de la région ?", "Quelles sont, selon vous, les spécificités du contrôle de gestion dans le secteur public par rapport au secteur privé, et comment y adaptez-vous vos pratiques ?"]','[]','{}','2026-08-27 13:26:21.963149') ON CONFLICT (id) DO NOTHING;